// HORDES — title-screen composition — layered grids for a 480x300 title card
//
// A1 ART TRACK. New file; nothing here is imported by the existing game yet.
// FORMAT (identical to src/sprites.js): a pixel grid is an array of rows, each
// row an array of integer palette indices, 0 = transparent, 1..9 = palette
// keys. `palette` maps those keys to CSS colours. Consume with the renderer's
// own painter:  renderer.drawGrid(g, asset.grid, asset.palette, x, y)
// `asset.rows` is the SAME data as digit strings ('0' = transparent) for
// tooling that reads text rows; it is DERIVED from the grid, never authored
// twice, so the two forms cannot drift (test/test_art_lint.mjs asserts it).
//
// Every palette reuses hues already present in the game's palettes
// (src/sprites.js sprite palettes + CONFIG.GROUND.THEMES in src/config.js).

// The startup menu overlays THIS, not the map. Native view is 480x300
// (CONFIG.VIEW_W/VIEW_H); the composition is view-sized, not world-sized.
//
// Layered on purpose: the sky and the frame are authored small and drawn at an
// integer SCALE (4x sky/frame, 3x horizon) because authoring a 120x75 sky beats
// authoring 144,000 pixels by hand and the upscale stays pixel-perfect.
// `composeTitle()` returns every layer with its grid already expanded to final
// view pixels and scale 1, so a consumer that only owns drawGrid can paint the
// whole card; `drawTitle(drawGrid, g)` is the one-call convenience.
import { makeAsset, scaleGrid } from './format.js';

export const TITLE_WIDTH = 480;
export const TITLE_HEIGHT = 300;

function makeLayer(spec) {
  const a = makeAsset(spec);
  return { ...a, x: spec.x, y: spec.y, scale: spec.scale };
}

