export const TITLE_ART = {
  id: 'TITLE_CARD',
  width: TITLE_WIDTH,
  height: TITLE_HEIGHT,
  layers: TITLE_LAYERS,
};

// Expanded layers (grid already at final size, scale 1). Computed once.
let _composed = null;
export function composeTitle() {
  if (_composed) return _composed;
  _composed = TITLE_LAYERS.map(L => ({
    id: L.id, x: L.x, y: L.y, scale: 1,
    palette: L.palette,
    grid: L.scale === 1 ? L.grid : scaleGrid(L.grid, L.scale),
  }));
  return _composed;
}

// One call paints the whole title card through the renderer's own painter:
//   drawTitle(r.drawGrid.bind(r), g)
export function drawTitle(drawGrid, g, ox = 0, oy = 0) {
  for (const L of composeTitle()) drawGrid(g, L.grid, L.palette, ox + L.x, oy + L.y);
}
